+let rec free_vars = (t: t): S.t =>
+  switch (t) {
+  | Var(x) => S.singleton(x)
+  | Type => S.empty
+  | Mem(a, b)
+  | App(a, b) => S.union(free_vars(a), free_vars(b))
+  | Pi(x, a, b) => S.union(free_vars(a), S.remove(x, free_vars(b)))
+  };
+
+let fresh = (x: string, avoid: S.t): string => {
+  let rec go = y => S.mem(y, avoid) ? go(y ++ "'") : y;
+  go(x);
+};
